<?php
 namespace OSS\Model; class BucketStat { public function getStorage() { return $this->storage; } public function getObjectCount() { return $this->objectCount; } public function getMultipartUploadCount() { return $this->multipartUploadCount; } public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (isset($xml->Storage) ) { $this->storage = intval($xml->Storage); } if (isset($xml->ObjectCount) ) { $this->objectCount = intval($xml->ObjectCount); } if (isset($xml->MultipartUploadCount) ) { $this->multipartUploadCount = intval($xml->MultipartUploadCount); } } private $storage; private $objectCount; private $multipartUploadCount; }